const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2400)}
function go(route){state.route=route;location.hash=route;render()}
function markDone(id){if(!state.completed.includes(id))state.completed.push(id); updateProgress()}
function updateProgress(){const pct=Math.round(state.completed.length/stages.length*100);$('#side-progress').style.width=pct+'%';$('#progress-label').textContent=`旅程进度 ${pct}%`}
function badge(status){const cls=status.includes('已')||status==='通过'?'ok':status.includes('异常')||status.includes('驳回')?'bad':status.includes('待')?'warn':'info';return `<span class="status ${cls}">${status}</span>`}
function pageHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`}
function renderShell(){
  $('#main-nav').innerHTML=`<div class="nav-group-label">工作台</div>`+navItems.map(n=>`<button class="nav-item ${state.route===n.id?'active':''}" data-route="${n.id}"><span class="nav-icon">${n.icon}</span><span class="nav-label">${n.label}</span>${n.id==='review'?'<span class="nav-badge">12</span>':''}</button>`).join('');
  $('#stage-strip').innerHTML=stages.map((s,i)=>`<button class="stage-chip ${state.route===s.id?'active':''} ${state.completed.includes(s.id)?'done':''}" data-route="${s.id}"><span class="num">${state.completed.includes(s.id)?'✓':i+1}</span><span>${s.label}</span></button>`).join('');
  const role=roles.find(r=>r.id===state.role);$('#role-name').textContent=role.name;$('#role-avatar').textContent=role.short;
  $('#role-menu').innerHTML=roles.map(r=>`<div class="role-option" data-role="${r.id}"><span class="avatar">${r.short}</span><span><b>${r.name}</b><p>${r.desc}</p></span></div>`).join('');
  const item=navItems.find(x=>x.id===state.route);$('#page-crumb').textContent=item?.label||'旅程总览'; updateProgress();
}
function overview(){return `${pageHead('INTELLIGENT ANALYTICS','知识从文档到组织能力','以场景为边界，让每一条知识可追溯、可确认、可审批、可消费。','<button class="btn" data-action="reset">重置演示</button><button class="btn primary" data-route="intake">开始旅程 →</button>')}
  <div class="grid cols-4">
    ${[['接入文档','128','↗','+18 本周'],['待确认知识','12','✓','3 个文档集'],['审批中','6','◎','2 位责任人'],['组织级知识','324','⬡','本月 +27']].map(x=>`<div class="card metric"><div class="metric-top"><span class="metric-icon">${x[2]}</span><span class="delta">${x[3]}</span></div><strong>${x[1]}</strong><small>${x[0]}</small></div>`).join('')}
  </div>
  <div class="card journey" style="margin-top:15px"><div class="card-title"><div><h3>端到端知识旅程</h3><p>点击阶段进入对应交互页面</p></div><span class="status info">收入经营场景</span></div><div class="journey-flow">${stages.map((s,i)=>`<div class="journey-node ${state.completed.includes(s.id)?'done':''} ${i===0&&!state.completed.length?'active':''}" data-route="${s.id}"><div class="orb">${s.icon}</div><b>${s.label}</b><small>${['集成 · 打标 · 建集','解析 · 质检 · 准入','规则 · 消歧 · 生成','确认 · 修改 · 补录','责任审批 · 专委认证','发布 · 版本 · 运营','检索 · 反馈 · 闭环'][i]}</small></div>`).join('')}</div><div class="handoff"><span class="handoff-label">角色接力</span>${roles.map(r=>`<span class="role-pill"><i></i>${r.name}</span>`).join('')}</div></div>
  <div class="split" style="margin-top:15px"><div class="panel"><div class="panel-head"><h3>今日待办</h3><button class="btn small" data-route="review">进入工作台</button></div><div class="panel-body">${[['确认“渠道收入预警”抽取结果','领域知识专家','12 条待确认'],['审批“中国区渠道库存归因”知识包','领域知识责任人','6 条待审批'],['组织级认证：收入预警规则集','领域专委会责任人','周三 15:00']].map((x,i)=>`<div class="feed-item"><span class="feed-dot">${i+1}</span><span><b>${x[0]}</b><p>${x[1]}</p></span><span class="status ${i===2?'info':'warn'}">${x[2]}</span></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h3>最近动态</h3><span class="status ok">实时</span></div><div class="panel-body">${[['王璐','完成 8 条知识确认','10:42'],['系统','Q3经营报告解析完成','10:18'],['领域专委会','认证 24 条组织级知识','昨天']].map(x=>`<div class="feed-item"><span class="feed-dot">${x[0][0]}</span><span><b>${x[0]}</b><p>${x[1]}</p></span><time>${x[2]}</time></div>`).join('')}</div></div></div>`}

function intake(){return `${pageHead('STAGE 01 · 领域知识管理员','知识接入与场景打标','先接入公开文档，再用场景标签组合形成可复用的特定文档集。','<button class="btn">接入日志</button><button class="btn primary" data-action="upload">＋ 上传文档</button>')}
  <div class="step-box"><h3>文档源</h3><p>自动集成公司公开知识源，也支持业务人员上传本地经验材料。</p><div class="source-cards">${[['财','财经知识圈','32 个文档'],['3M','3MS','46 个文档'],['iL','iLearning / wiki','38 个文档'],['＋','本地上传','12 个文档']].map((x,i)=>`<div class="source-card ${i<3?'on':''}"><span class="source-logo">${x[0]}</span><span><b>${x[1]}</b><small>${x[2]}</small></span>${i<3?'<span class="status ok" style="margin-left:auto">已同步</span>':''}</div>`).join('')}</div></div>
  <div class="panel" style="margin-top:15px"><div class="panel-head"><div><h3>文档库</h3></div><button class="btn primary small" data-action="create-set">将已选文档建为文档集</button></div>
    <div class="filter-bar">${[['责任中心','区域TOB'],['业务域','政企'],['对象','渠道业绩'],['主题','收入'],['适用区域','中国区']].map(x=>`<div class="filter-group"><span class="filter-label">${x[0]}</span><button class="tag active" data-filter="${x[0]}">${x[1]} <span class="x">×</span></button></div>`).join('')}<span class="filter-spacer"></span><div class="search"><span>⌕</span><input placeholder="搜索标题、作者…"></div></div>
    <div class="batch-bar"><span>✓ 已选择 ${state.selectedDocs.size} 个文档</span><span style="color:#93a2c0">标签组合命中 12 个文档</span><button class="btn small" data-action="apply-tags">批量打标签</button></div>
    <div class="table-wrap"><table class="data-table"><thead><tr><th><input type="checkbox" checked></th><th>文档</th><th>来源</th><th>责任中心</th><th>业务域</th><th>对象</th><th>主题</th><th>适用区域</th><th>状态</th><th></th></tr></thead><tbody>${demoDocs.map(d=>`<tr class="${state.selectedDocs.has(d.id)?'selected':''}"><td><input class="doc-check" data-id="${d.id}" type="checkbox" ${state.selectedDocs.has(d.id)?'checked':''}></td><td><div class="doc-title"><span class="file-icon">${d.type}</span><span><b>${d.name}</b><small>${d.owner} · ${d.time}</small></span></div></td><td>${d.source}</td><td>${d.tags[0]}</td><td>${d.tags[1]}</td><td>${d.tags[2]}</td><td>${d.tags[3]}</td><td>${d.tags[4]}</td><td>${badge(d.status)}</td><td><button class="btn small ghost" data-action="doc-detail" data-id="${d.id}">详情</button></td></tr>`).join('')}</tbody></table></div>
  </div><div class="action-bar"><span class="notice">标签来自智能分析场景语义体系，可按任意标签或标签组合筛选文档。</span><span class="spacer"></span><button class="btn primary" data-action="finish-intake">保存文档集并进入解析 →</button></div>`}

function parse(){const rows=demoDocs.slice(0,4);return `${pageHead('STAGE 02 · 系统自动化','多模态解析与原始知识准入','识别文本、表格、图表与音视频内容，并在抽取前完成质量和业务相关度检查。','<button class="btn">质量规则</button><button class="btn primary" data-action="run-parse">▶ 执行解析</button>')}
  <div class="grid cols-3"><div class="card card-pad"><div class="card-title"><div><h3>解析队列</h3><p>当前文档集：渠道收入预警</p></div>${badge('执行中')}</div><strong style="font-size:28px">12</strong><small style="color:var(--muted)">8 已完成 · 3 处理中 · 1 待处理</small></div><div class="card card-pad"><div class="card-title"><div><h3>格式覆盖</h3><p>PDF / Office / 图片 / 音视频</p></div><span class="metric-icon">◫</span></div><strong style="font-size:28px">8</strong><small style="color:var(--muted)">种企业文档格式</small></div><div class="card card-pad"><div class="card-title"><div><h3>平均质量</h3><p>文本完整性、表格识别、乱码检测</p></div></div><div class="quality-score"><div class="score-ring" style="--score:91" data-score="91"></div><div class="quality-bars"><div class="qbar"><span>文本完整性</span><span class="bar"><i style="width:97%"></i></span><b>97</b></div><div class="qbar"><span>表格识别率</span><span class="bar"><i style="width:89%"></i></span><b>89</b></div><div class="qbar"><span>业务相关度</span><span class="bar"><i style="width:93%"></i></span><b>93</b></div></div></div></div></div>
  <div class="panel" style="margin-top:15px"><div class="panel-head"><h3>文档解析明细</h3><span class="status info">阈值：质量 ≥ 80</span></div><table class="data-table"><thead><tr><th>文档</th><th>识别内容</th><th>页数/时长</th><th>解析进度</th><th>质量分</th><th>业务相关度</th><th>准入状态</th><th></th></tr></thead><tbody>${rows.map((d,i)=>`<tr><td><div class="doc-title"><span class="file-icon">${d.type}</span><b>${d.name}</b></div></td><td>${['文本 34 · 表格 8 · 图表 6','文本 18 · 表格 3','工作表 6 · 关系 24','文本 22 · 图表 9'][i]}</td><td>${[42,18,6,28][i]}</td><td><div class="qbar" style="grid-template-columns:100px 30px"><span class="bar"><i style="width:${d.quality||62}%"></i></span><b>${d.quality||62}%</b></div></td><td>${d.quality||'—'}</td><td>${[95,92,89,76][i]}%</td><td>${badge(i===3?'需人工确认':'准入')}</td><td><button class="btn small" data-action="preview-parse">预览</button></td></tr>`).join('')}</tbody></table></div><div class="action-bar"><span class="spacer"></span><button class="btn primary" data-action="finish-parse">确认准入并配置抽取 →</button></div>`}

function extract(){const set=docSets.find(s=>s.id===state.selectedSet),fields=state.fields[set.id];return `${pageHead('STAGE 03 · 领域知识管理员','按文档集配置抽取字段','同一场景下，不同标签组合形成不同文档集；每个文档集独立选择知识模型与抽取字段。','<button class="btn">抽取规则版本 V3</button><button class="btn primary" data-action="run-extract">运行抽取</button>')}
  <div class="schema-layout"><div class="panel"><div class="panel-head"><h3>文档集</h3><button class="btn small" data-action="new-set">＋</button></div><div class="set-list">${docSets.map(s=>`<div class="set-item ${s.id===set.id?'active':''}" data-set="${s.id}"><b>${s.name}</b><p>${s.filter}</p><small>${s.count} 份文档 · ${s.model}</small></div>`).join('')}</div></div>
    <div class="panel field-board"><div class="panel-head"><div><h3>${set.name}</h3><p style="font-size:9px;color:var(--muted);margin:3px 0 0">目标知识模型：${set.model}模型</p></div><button class="btn small" data-action="copy-schema">复制配置</button></div><div class="panel-body"><div class="notice">当前字段配置只作用于“${set.name}”。切换左侧文档集可看到完全不同的抽取字段。</div><div class="field-group" style="margin-top:18px"><div class="field-group-title">通用标签（自动继承）</div><div class="field-list">${['责任中心','业务域','对象','主题','适用区域','知识来源'].map(f=>`<span class="field-chip required"><i></i>${f}<span class="status info">必填</span></span>`).join('')}</div></div><div class="field-group"><div class="field-group-title">${set.model}专属字段（可配置）</div><div class="field-list">${fields.map(f=>`<span class="field-chip custom"><i></i>${f}<button class="remove" data-action="remove-field" data-field="${f}">×</button></span>`).join('')}<button class="add-field" data-action="add-field">＋ 添加字段</button></div></div><div class="grid cols-3" style="margin-top:22px"><div class="step-box"><h3>抽取约束</h3><p>只有文档中明确出现的规则才可生成；阈值必须带单位。</p><button class="btn small" data-action="edit-rule">编辑</button></div><div class="step-box"><h3>正例 / 反例</h3><p>3 个正例 · 2 个反例，用于约束策略与指标路径识别。</p><button class="btn small">查看示例</button></div><div class="step-box"><h3>质量门槛</h3><p>字段完整率 ≥ 85%；置信度低于 80% 自动转人工。</p><button class="btn small">调整</button></div></div><div class="action-bar"><span class="status ok">配置已自动保存</span><span class="spacer"></span><button class="btn primary" data-action="finish-extract">保存并生成结构化知识 →</button></div></div></div></div>`}

function review(){const rec=records.find(r=>r.id===state.selectedRecord);return `${pageHead('STAGE 04 · 领域知识专家','专家确认工作台','知识专家对 AI 生成的知识逐条确认、修改、放弃或补录，所有动作留痕。','<button class="btn" data-action="add-record">＋ 补录知识</button><button class="btn primary" data-action="batch-confirm">批量确认</button>')}
  <div class="review-layout"><div class="panel"><div class="panel-head"><h3>待确认记录</h3><span class="status warn">12 条</span></div><div class="record-list">${records.map(r=>`<div class="record ${r.id===rec.id?'active':''}" data-record="${r.id}"><div class="record-top"><b>${r.title}</b><span class="status info">${r.confidence}%</span></div><p>${r.id} · ${r.type}<br>${r.indicator} · ${r.scope}</p></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><h3>${rec.title}</h3><p style="font-size:9px;color:var(--muted);margin:3px 0 0">${rec.id} · 来源：2026年Q3区域TOB经营分析报告.pdf · 第 18 页</p></div>${badge(rec.status)}</div><div class="panel-body"><div class="form-grid"><div class="form-field"><label>知识类型</label><select><option>${rec.type}</option><option>维度归因</option><option>策略工具</option></select></div><div class="form-field"><label>预警指标</label><input value="${rec.indicator}"></div><div class="form-field"><label>规则逻辑</label><input value="${rec.logic}"></div><div class="form-field"><label>阈值条件</label><input value="${rec.threshold}"></div><div class="form-field full"><label>适用范围</label><input value="${rec.scope}"></div><div class="form-field full"><label>处置建议</label><textarea>${rec.advice}</textarea></div><div class="form-field full"><label>来源证据</label><div class="evidence">报告指出：当区域 TOB 政企渠道的<mark>销售收入环比下降达到 15%</mark>时，应触发黄色预警，并进一步下钻客户和产品线分析收入损失来源。<br><span style="color:#8793a7">AI 置信度 ${rec.confidence}% · 已与“销售收入”指标口径对齐</span></div></div></div><div class="action-bar"><button class="btn danger" data-action="drop-record">放弃</button><button class="btn" data-action="save-record">保存修改</button><span class="spacer"></span><button class="btn success" data-action="confirm-record">✓ 确认知识</button><button class="btn primary" data-action="submit-approval">提交审批 →</button></div></div></div></div>`}

function approval(){return `${pageHead('STAGE 05 · 责任审批 → 专委会定性','审批与组织级知识认证','领域知识责任人先判断知识是否 OK；领域专委会最终决定是否升级为组织级知识。','<button class="btn">查看调整历史</button>')}
  <div class="approval-flow"><div class="approval-step done"><span class="step-no">✓</span><h3>知识专家确认</h3><p>12 条知识已完成确认，含 2 条人工修订与 1 条补录。</p><div class="approval-meta"><span>执行人：王璐 · 领域知识专家</span><span>完成时间：今天 10:42</span></div></div><div class="approval-arrow">→</div><div class="approval-step ${state.approved?'done':'active'}"><span class="step-no">${state.approved?'✓':'2'}</span><h3>领域知识责任人审批</h3><p>核验准确性、适用范围与业务风险，决定知识是否可以发布。</p><div class="approval-meta"><span>审批人：陈思远</span><span>${state.approved?'已通过 · 今天 11:06':'待处理 · SLA 24 小时'}</span></div>${!state.approved?'<div class="action-bar"><button class="btn danger small" data-action="reject-owner">驳回</button><button class="btn success small" data-action="approve-owner">通过</button></div>':''}</div><div class="approval-arrow">→</div><div class="approval-step ${state.certified?'done':state.approved?'active':''}"><span class="step-no">${state.certified?'✓':'3'}</span><h3>领域专委会定性</h3><p>最终评议知识能否沉淀为跨团队复用的组织级知识。</p><div class="approval-meta"><span>召集人：刘建国 · 财经专委会</span><span>${state.certified?'已认证为组织级知识':state.approved?'待专委会确认':'等待责任人审批'}</span></div>${state.approved&&!state.certified?'<div class="action-bar"><button class="btn small" data-action="domain-only">仅领域知识</button><button class="btn primary small" data-action="certify">认证组织级</button></div>':''}</div></div>
  <div class="split" style="margin-top:15px"><div class="panel"><div class="panel-head"><h3>知识包摘要</h3>${badge(state.certified?'组织级知识':state.approved?'待认证':'待审批')}</div><div class="panel-body"><div class="grid cols-3"><div class="metric"><small>知识条目</small><strong>12</strong><span class="status ok">完整率 100%</span></div><div class="metric"><small>平均置信度</small><strong>93%</strong><span class="status ok">质量通过</span></div><div class="metric"><small>影响范围</small><strong>4</strong><span class="status info">业务对象</span></div></div><div class="notice">发布影响：2 个智能分析 Agent 将使用此知识包；组织级认证后，其他场景可发现并申请复用。</div></div></div><div class="panel"><div class="panel-head"><h3>审批轨迹</h3></div><div class="panel-body"><div class="timeline"><div class="timeline-item"><b>王璐提交审批</b><p>确认 9 条，修订 2 条，补录 1 条</p><time>今天 10:42</time></div>${state.approved?'<div class="timeline-item"><b>陈思远审批通过</b><p>内容准确，适用范围明确</p><time>今天 11:06</time></div>':''}${state.certified?'<div class="timeline-item"><b>财经专委会认证通过</b><p>具备跨团队复用价值，认证为组织级知识</p><time>今天 11:30</time></div>':''}</div></div></div></div>${state.certified?'<div class="action-bar"><span class="spacer"></span><button class="btn primary" data-route="publish">进入发布入库 →</button></div>':''}`}

function publishPage(){return `${pageHead('STAGE 06 · 系统自动化','知识发布与运营','发布审批通过的知识包，保留版本、来源与审批链路，并进入全生命周期运营。',`<button class="btn">版本历史</button><button class="btn primary" data-action="publish-now">${state.published?'已发布 V1.0':'发布到正式库'}</button>`)}
  <div class="grid cols-4">${[['待发布','12','warn'],['正式知识','324','ok'],['本月新增','27','info'],['待复审','18','warn']].map(x=>`<div class="card metric"><small>${x[0]}</small><strong>${x[1]}</strong><span class="status ${x[2]}">${x[0]==='正式知识'?'可被 Agent 消费':'实时更新'}</span></div>`).join('')}</div><div class="split" style="margin-top:15px"><div class="panel"><div class="panel-head"><h3>发布清单 · 中国区渠道收入预警知识包</h3>${badge(state.published?'正式':'待发布')}</div><table class="data-table"><thead><tr><th>知识编码</th><th>知识名称</th><th>类型</th><th>级别</th><th>版本</th><th>责任人</th><th>有效期</th></tr></thead><tbody>${records.concat(records).slice(0,5).map((r,i)=>`<tr><td>KA-${String(i+1).padStart(4,'0')}</td><td>${r.title}</td><td>${r.type}</td><td>${badge(i<3?'组织级':'领域级')}</td><td>V1.0</td><td>${['陈思远','陈思远','李文青','赵宁','赵宁'][i]}</td><td>2027-10-12</td></tr>`).join('')}</tbody></table></div><div class="panel"><div class="panel-head"><h3>生命周期策略</h3></div><div class="panel-body">${[['定期复审','每 12 个月','已启用'],['过期提醒','到期前 30 天','已启用'],['Agent 反馈','错误/过期/场景不适配','自动建单'],['下线影响评估','引用与调用频次','强制执行']].map(x=>`<div class="feed-item"><span class="feed-dot">✓</span><span><b>${x[0]}</b><p>${x[1]}</p></span><span class="status ok">${x[2]}</span></div>`).join('')}</div></div></div><div class="action-bar"><span class="spacer"></span><button class="btn primary" data-action="finish-publish" ${state.published?'':'disabled'}>体验 Agent 消费 →</button></div>`}

function consume(){const q=state.query.toLowerCase();const cards=[{t:'渠道销售收入环比降幅预警',type:'预警规则',desc:'当销售收入环比下降 ≥ 15% 时触发黄色预警，并下钻客户与产品线。',scope:'区域TOB · 政企 · 中国区',score:'4.9'},{t:'销售收入维度归因路径',type:'维度归因',desc:'从销售收入出发，按渠道类型、客户、产品线与区域逐层归因。',scope:'区域TOB · 渠道业绩',score:'4.8'},{t:'库存周转异常改进策略',type:'策略工具',desc:'连续两期库存周转天数超过 45 天时，联动 Sell-out 与在途库存复核。',scope:'区域TOB · 渠道库存',score:'4.7'}].filter(x=>{if(!q)return true;const corpus=(x.t+x.desc+x.scope).toLowerCase();return corpus.includes(q)||Array.from(q.replace(/\s/g,'')).every(ch=>corpus.includes(ch))});return `${pageHead('STAGE 07 · AGENT & 业务用户','知识检索与消费闭环','通过关键词、标签或语义检索找到可信知识；每次引用、评分与反馈都会回流运营。','<button class="btn">MCP 接入说明</button>')}
  <div class="search-hero"><div><h2>问知识，而不只是搜文档</h2><p>已接入 324 条正式知识 · 其中 218 条组织级知识</p></div><div class="big-search"><input id="knowledge-query" value="${esc(state.query)}" placeholder="例如：收入下降多少需要预警？"><button data-action="knowledge-search">语义检索</button></div></div><div class="filter-bar" style="margin-top:15px;border:1px solid var(--line);border-radius:13px"><span class="filter-label">知识类型</span><button class="tag active">全部 324</button><button class="tag">预警规则 86</button><button class="tag">维度归因 72</button><button class="tag">指标路径 98</button><button class="tag">策略工具 68</button><span class="filter-spacer"></span><span class="status ok">MCP 已连接</span></div><div class="grid cols-3" style="margin-top:15px">${cards.length?cards.map((c,i)=>`<article class="knowledge-card"><span class="status info">${c.type}</span><h3>${c.t}</h3><p>${c.desc}</p><div class="tags"><span class="tag">${c.scope.split(' · ')[0]}</span><span class="tag">${c.scope.split(' · ')[1]}</span>${c.scope.split(' · ')[2]?`<span class="tag">${c.scope.split(' · ')[2]}</span>`:''}</div><footer><span>组织级 · V1.0 · 可追溯</span><span class="stars">★★★★★ ${c.score}</span></footer><div class="action-bar"><button class="btn small" data-action="view-knowledge">查看溯源</button><span class="spacer"></span><button class="btn primary small" data-action="use-knowledge">交给 Agent</button></div></article>`).join(''):'<div class="card empty" style="grid-column:1/-1">没有找到匹配知识，请尝试“收入预警”或“库存周转”。</div>'}</div><div class="grid cols-3" style="margin-top:15px"><div class="card metric"><small>近 30 天 Agent 调用</small><strong>8,642</strong><span class="delta">↑ 18.6%</span></div><div class="card metric"><small>知识命中率</small><strong>86.4%</strong><span class="delta">↑ 3.2%</span></div><div class="card metric"><small>反馈闭环率</small><strong>92%</strong><span class="status info">11 条处理中</span></div></div>`}

function renderPage(){const map={overview,intake,parse,extract,review,approval,publish:publishPage,consume};$('#page').innerHTML=(map[state.route]||overview)()}
function render(){renderShell();renderPage();bindDynamic()}
function bindDynamic(){
  document.querySelectorAll('[data-route]').forEach(el=>el.onclick=()=>go(el.dataset.route));
  document.querySelectorAll('[data-set]').forEach(el=>el.onclick=()=>{state.selectedSet=el.dataset.set;render()});
  document.querySelectorAll('[data-record]').forEach(el=>el.onclick=()=>{state.selectedRecord=el.dataset.record;render()});
  document.querySelectorAll('.doc-check').forEach(el=>el.onchange=()=>{const id=+el.dataset.id;el.checked?state.selectedDocs.add(id):state.selectedDocs.delete(id);render()});
  document.querySelectorAll('[data-action]').forEach(el=>el.onclick=(e)=>handleAction(el.dataset.action,el,e));
}
function modal(title,body,confirm='完成',onConfirm){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>${title}</h3><button class="modal-close" data-close>×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="btn" data-close>取消</button><button class="btn primary" id="modal-confirm">${confirm}</button></div></div></div>`;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);$('#modal-confirm').onclick=()=>{onConfirm?.();closeModal()}}
function closeModal(){$('#modal-root').innerHTML=''}
function handleAction(a,el){
  if(a==='toggle-help') return modal('Demo 操作说明','<div class="notice">这是一个端到端可交互原型。可从左侧或顶部阶段导航切换页面；右上角可切换四类角色视角。</div><div style="margin-top:14px" class="timeline"><div class="timeline-item"><b>知识管理员</b><p>接入、打标、建文档集、配置不同抽取字段</p></div><div class="timeline-item"><b>知识专家</b><p>确认、修改、放弃与补录知识</p></div><div class="timeline-item"><b>责任人 + 专委会</b><p>分别负责知识审批和组织级定性</p></div></div>','知道了');
  if(a==='reset'){state.completed=[];state.approved=false;state.certified=false;state.published=false;toast('演示状态已重置');return render()}
  if(a==='upload') return modal('上传本地文档','<div class="check-row"><input type="checkbox" checked><span><b>经营分析报告_Q3.pdf</b><small>PDF · 12.4 MB · 待识别元数据</small></span></div><div class="form-field"><label>默认责任中心</label><select><option>区域TOB</option><option>ICT</option></select></div>','上传并解析',()=>toast('文档已加入接入队列'));
  if(a==='apply-tags') return modal('批量打场景标签',`<div class="notice">将对已选 ${state.selectedDocs.size} 份文档应用以下标签。</div><div class="field-list" style="margin-top:14px">${['责任中心：区域TOB','业务域：政企','对象：渠道业绩','主题：收入','适用区域：中国区'].map(x=>`<span class="field-chip required"><i></i>${x}</span>`).join('')}</div>`,'应用标签',()=>toast(`已为 ${state.selectedDocs.size} 份文档打标`));
  if(a==='create-set') return modal('新建特定文档集','<div class="form-field"><label>文档集名称</label><input value="中国区 · 渠道收入预警"></div><div class="form-field" style="margin-top:12px"><label>目标知识模型</label><select><option>预警规则模型</option><option>维度归因模型</option><option>指标路径模型</option><option>策略工具模型</option></select></div><div class="notice" style="margin-top:12px">该文档集将保存当前标签组合和 3 份已选文档。后续可为它单独配置抽取字段。</div>','创建文档集',()=>toast('文档集已创建，可进入解析'));
  if(a==='doc-detail'||a==='preview-parse'||a==='view-knowledge') return modal('来源与解析详情','<div class="notice">所有知识保留源文档、页码/单元格、抽取规则版本、专家操作与审批链路，支持全程追溯。</div><div class="evidence" style="margin-top:14px">来源片段：当区域 TOB 政企渠道的销售收入环比下降达到 15% 时，应触发黄色预警……</div>','关闭');
  if(a==='finish-intake'){markDone('intake');toast('文档集已保存');return go('parse')}
  if(a==='run-parse'){toast('解析任务已启动：文本、表格与图表并行识别');setTimeout(()=>toast('12 份文档解析完成，1 份需人工确认'),800);return}
  if(a==='finish-parse'){markDone('parse');toast('原始知识已准入');return go('extract')}
  if(a==='add-field') return modal('添加抽取字段','<div class="form-field"><label>字段名称</label><input id="new-field" value="影响等级"></div><div class="form-field" style="margin-top:12px"><label>字段说明</label><textarea>用于标记规则触发后的业务影响等级</textarea></div>','添加',()=>{const v=document.querySelector('#new-field')?.value||'影响等级';state.fields[state.selectedSet].push(v);toast('字段已添加');render()});
  if(a==='remove-field'){state.fields[state.selectedSet]=state.fields[state.selectedSet].filter(f=>f!==el.dataset.field);toast('字段已移除');return render()}
  if(a==='copy-schema')return modal('复制字段配置','<div class="form-field"><label>复制到文档集</label><select><option>请选择目标文档集</option><option>中国区 · 渠道库存归因</option><option>亚太区 · 渠道激励策略</option></select></div><div class="notice" style="margin-top:12px">复制后仍可在目标文档集中独立调整，不会互相影响。</div>','复制',()=>toast('配置已复制'));
  if(a==='run-extract'){toast('抽取任务运行中：已生成 12 条结构化知识');return}
  if(a==='finish-extract'){markDone('extract');toast('结构化知识已生成并完成语义消歧');return go('review')}
  if(a==='save-record'){toast('修改已保存，调整原因已记录');return}
  if(a==='confirm-record'){records.find(r=>r.id===state.selectedRecord).status='已确认';toast('知识已确认');return render()}
  if(a==='drop-record')return modal('放弃这条知识','<div class="form-field"><label>放弃原因（必填）</label><textarea placeholder="例如：规则已失效或不适用于当前范围"></textarea></div>','确认放弃',()=>toast('知识已放弃并记录原因'));
  if(a==='add-record')return modal('补录知识','<div class="form-field"><label>知识类型</label><select><option>预警规则</option><option>维度归因</option><option>指标路径</option><option>策略工具</option></select></div><div class="form-field" style="margin-top:10px"><label>知识名称</label><input placeholder="请输入"></div><div class="form-field" style="margin-top:10px"><label>补录说明</label><textarea placeholder="说明来源与适用范围"></textarea></div>','保存补录',()=>toast('知识已补录并标记人工来源'));
  if(a==='batch-confirm'){toast('已批量确认 9 条高置信知识');return}
  if(a==='submit-approval'){markDone('review');toast('知识包已提交领域知识责任人');return go('approval')}
  if(a==='approve-owner'){state.approved=true;toast('审批通过，已流转至领域专委会');return render()}
  if(a==='reject-owner')return modal('驳回知识包','<div class="form-field"><label>驳回原因</label><textarea>适用范围需细化至政企渠道，并补充阈值口径。</textarea></div>','确认驳回',()=>toast('已退回领域知识专家调整'));
  if(a==='certify'){state.certified=true;markDone('approval');toast('已认证为组织级知识');return render()}
  if(a==='domain-only'){state.certified=true;markDone('approval');toast('已定性为领域级知识');return render()}
  if(a==='publish-now'){state.published=true;markDone('publish');toast('V1.0 已发布至正式知识库');return render()}
  if(a==='finish-publish')return go('consume');
  if(a==='knowledge-search'){state.query=$('#knowledge-query').value.trim();markDone('consume');toast(state.query?'已完成语义检索':'请输入检索问题');return render()}
  if(a==='use-knowledge'){toast('已将知识与来源证据交给智能分析 Agent');return}
  if(a==='new-set'||a==='edit-rule') return toast('此操作在 Demo 中以示意形式呈现');
}
$('#role-switcher').onclick=e=>{if(e.target.closest('.role-option'))return;$('#role-switcher').classList.toggle('open')};
document.addEventListener('click',e=>{const r=e.target.closest('[data-role]');if(r){state.role=r.dataset.role;$('#role-switcher').classList.remove('open');toast(`已切换为${roles.find(x=>x.id===state.role).name}视角`);render()}});
window.addEventListener('hashchange',()=>{state.route=location.hash.slice(1)||'overview';render()});
render();
